import '@/components/report/design/components/customTable/cus-theme.less';
import cellTypes from '@/constants/cellTypes';
import licenseKey from '@/constants/licenseKey';
import { HotTable, HotTableClass } from '@handsontable/react';
import { NG, NGLayout, useSelector } from '@newgrand/udp-ui';
import { useLocation } from '@umijs/max';
import Core from 'handsontable/core';
import 'handsontable/dist/handsontable.full.min.css';
import { registerAllModules } from 'handsontable/registry';
import { forwardRef, useCallback, useEffect, useImperativeHandle, useMemo, useRef, useState } from 'react';
import { handleBorderInSelection } from '../../design/components/customTable/utils/frozen';
import { closeFilterPopup } from '../plugins/filterRender/filterModal';
import PreviewTableSheets from '../tableSheets';
import { releasePreviewStyleRules } from '../tableSheets/styleSheetRegistry';
import { getIsMobile } from '../utils/isMobile';
import style from './index.less';
import settings from './settings';
import './style.less';
import { registerPreviewTable, unregisterPreviewTable } from './tableRegistry';
import { usePreviewTableDormancy } from './usePreviewTableDormancy';
// register Handsontable's modules
registerAllModules();

interface PreviewTableProps {
  className?: string;
  // 是否不渲染sheet
  noSheets?: boolean;
  isPortal?: boolean;
  /**
   * 是否展示「隐藏当前行 / 取消隐藏」右键项（打印预览接口 previewEditStatus === 1 时为 true）。
   * 未传时默认 true，兼容设计预览等非打印预览页。
   */
  previewRowHideEnabled?: boolean;
}
export interface PreviewTableAPI {
  getHotInstance: () => HotTableClass;
}

const PreviewTable = forwardRef<PreviewTableAPI, PreviewTableProps>(
  ({ className, noSheets = false, isPortal, previewRowHideEnabled = true }, ref) => {
    const { hotLoading } = useSelector((state) => {
      return state[NG.getPageInstance().props.getDvaName()];
    });
    const isReport = useLocation().pathname.includes('TableManager');
    const tableRef = useRef<HotTableClass | null>(null);
    const visibilityRootRef = useRef<HTMLDivElement>(null);
    const [tableMounted, setTableMounted] = useState(true);
    const inactiveTimerRef = useRef<number>();
    const idleCallbackRef = useRef<number>();
    const tablePausedRef = useRef(false);
    /**
     * 右键目标坐标。beforeOnCellContextMenu 里同步写入 ref，并写入 hot.__previewCmCoords（hidden/callback 的 this 即 Core，与 ref 双保险）。
     */
    const contextMenuTargetRef = useRef<{ row: number; col: number } | null>(null);
    /** 按行记录预览蒙层，菜单显隐只信此 Set，避免合并格 meta / col 判断误差导致「全局」误判 */
    const previewMaskedRowsRef = useRef<Set<number>>(new Set());

    const PREVIEW_CM_COORDS = '__previewCmCoords';

    function getPreviewCmTarget(hot: Core): { row: number; col: number } | null {
      const cm = (hot as unknown as Record<string, unknown>)[PREVIEW_CM_COORDS] as
        | { row: number; col: number }
        | undefined;
      if (cm && typeof cm.row === 'number' && typeof cm.col === 'number') return cm;
      return contextMenuTargetRef.current;
    }
    /**
     * 获取hotInstance
     */
    function getHotInstance(): HotTableClass {
      return tableRef.current!;
    }

    function getHotCore(): Core | null | undefined {
      return tableRef.current?.hotInstance;
    }

    const MASK_CLASS = 'htPreviewMaskedCol';

    function addClassName(origin: unknown, classToken: string) {
      const classes = String(origin ?? '')
        .split(/\s+/)
        .filter(Boolean);
      if (!classes.includes(classToken)) {
        classes.push(classToken);
      }
      return classes.join(' ');
    }

    function removeClassName(origin: unknown, classToken: string) {
      return String(origin ?? '')
        .split(/\s+/)
        .filter(Boolean)
        .filter((c) => c !== classToken)
        .join(' ');
    }

    function rowHasForcePageBreak(row: number) {
      const hot = getHotCore();
      if (!hot || row < 0) return false;
      return Boolean((hot.getCellMeta(row, 0) as any)?.forcePageBreak);
    }

    function maskCurrentRow(row: number) {
      const hot = getHotCore();
      if (!hot || row < 0) return;
      previewMaskedRowsRef.current.add(row);
      const colCount = hot.countCols();
      for (let col = 0; col < colCount; col++) {
        const meta = hot.getCellMeta(row, col) as any;
        hot.setCellMeta(row, col, 'className', addClassName(meta?.className, MASK_CLASS));
      }
      hot.render();
    }

    function unmaskCurrentRow(row: number) {
      const hot = getHotCore();
      if (!hot || row < 0) return;
      previewMaskedRowsRef.current.delete(row);
      const colCount = hot.countCols();
      for (let col = 0; col < colCount; col++) {
        const meta = hot.getCellMeta(row, col) as any;
        hot.setCellMeta(row, col, 'className', removeClassName(meta?.className, MASK_CLASS));
      }
      hot.render();
    }

    const cancelScheduledUnmount = useCallback(() => {
      if (inactiveTimerRef.current !== undefined) {
        window.clearTimeout(inactiveTimerRef.current);
        inactiveTimerRef.current = undefined;
      }
      if (idleCallbackRef.current !== undefined) {
        const cancelIdleCallback = (window as any).cancelIdleCallback;
        if (cancelIdleCallback) cancelIdleCallback(idleCallbackRef.current);
        else window.clearTimeout(idleCallbackRef.current);
        idleCallbackRef.current = undefined;
      }
    }, []);

    const pauseTable = useCallback(() => {
      if (tablePausedRef.current) return;
      tablePausedRef.current = true;
      closeFilterPopup();
      const hot = tableRef.current?.hotInstance;
      hot?.unlisten();
      hot?.suspendExecution();

      cancelScheduledUnmount();
      inactiveTimerRef.current = window.setTimeout(() => {
        const unmount = () => {
          idleCallbackRef.current = undefined;
          const hot = tableRef.current?.hotInstance;
          if (hot) releasePreviewStyleRules(hot);
          setTableMounted(false);
        };
        const requestIdleCallback = (window as any).requestIdleCallback;
        idleCallbackRef.current = requestIdleCallback
          ? requestIdleCallback(unmount, { timeout: 1000 })
          : window.setTimeout(unmount, 0);
      }, 300);
    }, [cancelScheduledUnmount]);

    const resumeTable = useCallback(() => {
      cancelScheduledUnmount();
      if (!tablePausedRef.current) return;
      tablePausedRef.current = false;
      if (!tableMounted) {
        setTableMounted(true);
        return;
      }
      const hot = tableRef.current?.hotInstance;
      hot?.resumeExecution();
      hot?.listen();
      hot?.render();
    }, [cancelScheduledUnmount, tableMounted]);

    usePreviewTableDormancy(visibilityRootRef, {
      onHidden: pauseTable,
      onVisible: resumeTable
    });

    const handleTableRef = useCallback((table: HotTableClass | null) => {
      const previousTable = tableRef.current;
      if (previousTable && previousTable !== table) {
        unregisterPreviewTable(previousTable);
      }

      tableRef.current = table;
      if (table) {
        registerPreviewTable(table);
        window['handsonTable'] = table;
      } else if (window['handsonTable'] === previousTable) {
        window['handsonTable'] = null;
      }
    }, []);

    useEffect(() => {
      return () => {
        cancelScheduledUnmount();
        closeFilterPopup();
        const table = tableRef.current;
        if (table) unregisterPreviewTable(table);
        tableRef.current = null;
        tablePausedRef.current = false;
      };
    }, [cancelScheduledUnmount]);

    const MemoTable = useMemo(() => {
      let className = getIsMobile() ? 'mobileTable' : '';
      if (isPortal) {
        className += ' portalTable';
      }

      return (
        <HotTable
          ref={handleTableRef}
          renderAllRows={false}
          renderAllColumns={false}
          tableClassName={style.customTable}
          className={isReport ? className : `${className} printWrap`}
          // 取消超出点击后自动滚动的行为
          beforeViewportScrollHorizontally={() => false}
          beforeKeyDown={(event) => {
            const e = event as KeyboardEvent;
            if (!(e.ctrlKey || e.metaKey) || e.key.toLowerCase() !== 'c') return;
            const hot = getHotCore();
