  //     hotInstance?.updateSettings({
  //       rowHeaders: true,
  //       colHeaders: true
  //     });
  //     clearTimeout(timer);
  //   }, 1000);
  // }

  NG.getPageInstance().umiDispatch({
    type: 'updateHotLoading',
    payload: false
  });
}

