.treeHeader {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: flex-start;
  height: 100%;
  padding: 0 4px;
}

// 外层虚线
.row-expand-icon {
  position: relative;
  position: relative;
  z-index: 1;
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 100%;
  transition: all 0.3s ease-out;

  &::before {
    position: absolute;
    top: 0;
    bottom: 0;
    left: 50%;
    border-right: 1px dotted #d9d9d9;
    content: '';
  }

  &::after {
    position: absolute;
    top: 50%;
    right: 0;
    left: 50%;
    border-top: 1px dotted #d9d9d9;
    content: '';
  }
}

.row-expand-icon-last {
  &::before {
    transform: translateY(-50%);
  }
}

.icon {
  position: relative;
  z-index: 2;
  width: 16px;
  height: 16px;
  color: var(--primary-color);
  background-color: #fff;
  border: 1px solid var(--border-color-split);
  border-radius: 2px;
  cursor: pointer;

  &::after,
  &::before {
    position: absolute;
    top: 3px;
    bottom: 3px;
    left: 50%;
    width: 1px;
    background: currentcolor;
    transform: translate(-50%);
    transition: transform 0.3s ease-out;
    content: '';
  }

  &::after {
    transform: translate(-50%) rotate(90deg);
  }

  &:hover {
    box-shadow: var(--primary-color-1) 0px 1px 3px, var(--primary-color-2) 0px 1px 2px;
  }
}

// 展开
.icon-expanded {
  &::before {
    transform: translate(-50%) rotate(90deg);
  }

  &::after {
    transform: translate(-50%) rotate(270deg);
  }
}

// 收起
.icon-collapsed {
  &::before {
    transform: translate(-50%) rotate(-90deg);
  }

  &::after {
    transform: translate(-50%) rotate(180deg);
  }
}

