import Handsontable from 'handsontable';
import { HotTextRender } from '../textRender/render';
import { setStyleBorders } from '../utils/style';
import { setValidClassName } from '../utils/valid';

export default function treeRender(
  this: Handsontable.Core,
  instance: Handsontable.Core,
  TD: HTMLTableCellElement,
  row: number,
  col: number,
  prop: string | number,
  value: any,
  cellProperties: Handsontable.CellProperties
) {
  // 设置htCoord
  TD.setAttribute('htCoord', `${row}-${col}`);

  // 添加标识，在fieldRender中会校验是否有效
  if (TD.parentNode?.nodeName === 'TR') {
    TD.parentElement?.setAttribute('treeCoord', `${row}-${col}`);
  }

  const newCellProperties = {
    ...cellProperties,
    valid: true,
    editor: false,
    trimWhitespace: true
  };

  // 初始化时 添加或删除 htCustomInvalid
  setValidClassName(TD, cellProperties.className as string);

  // 设置边框
  setStyleBorders(TD, cellProperties?.borders);

  // 自定义渲染
  HotTextRender.apply(this, [instance, TD, row, col, prop, value, newCellProperties]);
}

