import Handsontable from 'handsontable';
import { createRoot } from 'react-dom/client';
import { empty } from '../../design/components/customTable/plugins/utils/hot-utils';
import { getCellRootKey, releaseCellReactRoots } from './cellRootLifecycle';

export const getBorderByDirection = (direction, border, TD: HTMLTableCellElement) => {
  const borderClass = `htBorder_${direction.charAt(0).toUpperCase() + direction.slice(1)}_${border?.width ?? 1}_${(
    border?.color ?? '#000'
  ).slice(1)}`;

  if (['top', 'bottom', 'left', 'right'].includes(direction)) {
    TD.classList.add(borderClass);
  }
};

/**
 * 判断当前单元格是否在冻结区域
 * 是的话，缓存react组件，防止重复渲染
 */
export function isInFrozen(
  row: number,
  col: number,
  cellProperties: Handsontable.CellProperties,
  hot: Handsontable.Core
) {
  // 如果fixedColumnsStart有值，代表有冻结
  if (cellProperties.fixedColumnsStart) {
    const fixedRowsStart = hot.getSettings().fixedRowsTop;
    if (row <= (fixedRowsStart ?? 0) && col <= (cellProperties.fixedColumnsStart ?? 0)) {
      return true;
    }
  }
  return false;
}

export function optimizeRender(TD, row, col, _lazyRender?: boolean) {
  const rootKey = getCellRootKey(row, col);
  releaseCellReactRoots(TD, rootKey);
  if (TD[rootKey]) return;

  empty(TD);
  TD[rootKey] = createRoot(TD);
}

export function getRenderCellProperties(
  instance: Handsontable.Core,
  row: number,
  col: number,
  cellProperties: Handsontable.CellProperties
): (Handsontable.CellProperties & { row: number; col: number }) | null {
  if (row === cellProperties.row && col === cellProperties.col) {
    return cellProperties as Handsontable.CellProperties & { row: number; col: number };
  }

  const mergePlugin = instance.getPlugin('mergeCells') as any;
  const mergeParent = mergePlugin?.mergedCellsCollection?.get(row, col);
  if (!mergeParent) return null;

  return {
    ...instance.getCellMeta(mergeParent.row, mergeParent.col),
    row: mergeParent.row,
    col: mergeParent.col,
    rowspan: mergeParent.rowspan,
    colspan: mergeParent.colspan
  };
}

export function resetCellRenderStyle(TD: HTMLTableCellElement, row: number, col: number) {
  TD.setAttribute('htCoord', `${row}-${col}`);
  TD.removeAttribute('size');
  TD.style.padding = '';
  TD.style.borderTop = '';
  TD.style.borderRight = '';
  TD.style.borderBottom = '';
  TD.style.borderLeft = '';
  TD.style.display = '';

  if (TD.parentElement?.firstElementChild !== TD) {
    TD.style.height = '';
  }
}

export function resetSkippedCellRender(TD: HTMLTableCellElement, row: number, col: number) {
  const td = TD as any;
  releaseCellReactRoots(td);

  empty(TD);
  TD.className = '';
  TD.removeAttribute('rowspan');
  TD.removeAttribute('colspan');
  TD.removeAttribute('size');
  TD.setAttribute('htCoord', `${row}-${col}`);
  TD.style.padding = '';
  TD.style.borderTop = '';
  TD.style.borderRight = '';
  TD.style.borderBottom = '';
  TD.style.borderLeft = '';
  TD.style.height = '';
  TD.style.display = '';
}

/**
 * 1、判断当前单元格是否是最后一行
 * 2、返回父节点坐标
 * @param cellProperties
 * @param instance
 * @returns
 */
export function setIsLastTreeChildren(cellProperties: Handsontable.CellProperties, instance: Handsontable.Core) {
  let parentCoord: number[] | null = null;

  if (cellProperties.treeParent !== null && cellProperties.treeParent >= 0) {
    // 得到父节点坐标
    parentCoord = [cellProperties.treeParent, cellProperties.col];
    const parentCellMeta = instance.getCellMeta(parentCoord[0], parentCoord[1]);

    if (Math.max(...(parentCellMeta?.children ?? [])) === Number(cellProperties.row)) {
      cellProperties.isLast = true;
    }
  }

  return { parentCoord };
}

