            if (!text && text !== '') return;
            e.preventDefault();
            if ((navigator as any).clipboard?.writeText) {
              (navigator as any).clipboard.writeText(text);
            } else {
              const textarea = document.createElement('textarea');
              textarea.value = text;
              document.body.appendChild(textarea);
              textarea.select();
              document.execCommand('copy');
              document.body.removeChild(textarea);
            }
          }}
          afterGetRowHeader={(row, TH) => {
            TH.className = `htMiddle${rowHasForcePageBreak(row) ? ' htForcePageBreakHeader' : ''}`;
          }}
          afterRenderer={(TD, row) => {
            TD.classList.toggle('htForcePageBreakRow', rowHasForcePageBreak(row));
          }}
          afterSetCellMeta={(row, col, key, value) => {
            if (key === 'cellType') {
              if (
                value === cellTypes.chart ||
                value === cellTypes.slash ||
                value === cellTypes.image ||
                value === cellTypes.tree
              ) {
                getHotCore()?.setCellMeta(row, col, 'type', value);
              }
            }
          }}
          afterRowResize={(newSize, row) => {
            NG.getPageInstance().umiDispatch({
              type: 'updateRowResize',
              payload: { row, newSize }
            });
          }}
          afterColumnResize={(newSize, col) => {
            NG.getPageInstance().umiDispatch({
              type: 'updateColResize',
              payload: { col, newSize }
            });
          }}
          // 在选择范围时去除冻结横跨的多余边框
          beforeSetRangeEnd={() => {
            const hot = getHotCore();
            if (!hot) return;
            return NG.debounce(handleBorderInSelection(hot), 200);
          }}
          beforeOnCellContextMenu={(_event, coords) => {
            const hot = getHotCore();
            if (coords && typeof coords.row === 'number' && typeof coords.col === 'number') {
              const payload = { row: coords.row, col: coords.col };
              contextMenuTargetRef.current = payload;
              if (hot) {
                (hot as unknown as Record<string, unknown>)[PREVIEW_CM_COORDS] = payload;
              }
            }
          }}
          // 勿在 afterContextMenuHide 里清空 contextMenuTargetRef：菜单项 callback 往往在 hide 之后才执行，清空会导致读不到坐标
          // 右键菜单：复制“看得见的内容”（优先 formatData）
          contextMenu={{
            items: {
              copyCellText: {
                name: '复制单元格内容',
                callback: (_key, selection) => {
                  const hot = getHotCore();
                  if (!hot || !selection || !selection.length) return;
                  const { row, col } = selection[0].start;
                  const meta = hot.getCellMeta(row, col) as any;
                  const raw = meta?.formatData ?? hot.getDataAtCell(row, col);
                  const text = raw == null ? '' : String(raw);
                  if (!text && text !== '') return;
                  if ((navigator as any).clipboard?.writeText) {
                    (navigator as any).clipboard.writeText(text);
                  } else {
                    const textarea = document.createElement('textarea');
                    textarea.value = text;
                    document.body.appendChild(textarea);
                    textarea.select();
                    document.execCommand('copy');
                    document.body.removeChild(textarea);
                  }
                }
              },
              hiddenCurrentRow: {
                name: '隐藏当前行',
                hidden(this: Core) {
                  if (!previewRowHideEnabled) return true;
                  const t = getPreviewCmTarget(this);
                  if (!t) return true;
                  if (t.col >= 0) return true;
                  return previewMaskedRowsRef.current.has(t.row);
                },
                callback(this: Core) {
                  if (!previewRowHideEnabled) return;
                  const t = getPreviewCmTarget(this);
                  if (!t || t.col >= 0) return;
                  maskCurrentRow(t.row);
                }
              },
              showCurrentRow: {
                name: '取消隐藏当前行',
                hidden(this: Core) {
                  if (!previewRowHideEnabled) return true;
                  const t = getPreviewCmTarget(this);
                  if (!t) return true;
                  if (t.col >= 0) return true;
                  return !previewMaskedRowsRef.current.has(t.row);
                },
                callback(this: Core) {
                  if (!previewRowHideEnabled) return;
                  const t = getPreviewCmTarget(this);
                  if (!t || t.col >= 0) return;
                  unmaskCurrentRow(t.row);
                }
              }
            }
          }}
          settings={settings}
          licenseKey={licenseKey}
        />
      );
    }, [handleTableRef, previewRowHideEnabled]);

    useImperativeHandle(ref, () => {
      return { getHotInstance };
    });
    return (
      <NGLayout className={className}>
        <div ref={visibilityRootRef} className={style.visibilityRoot}>
          {tableMounted ? (
            <NGLayout loading={getIsMobile() ? false : hotLoading}>
              <NGLayout className={noSheets ? style.tableContextNoSheets : style.tableContext}>{MemoTable}</NGLayout>
              <PreviewTableSheets tableRef={tableRef} className={style.previewSheets} noSheets={noSheets} />
            </NGLayout>
          ) : null}
        </div>
      </NGLayout>
    );
  }
);

export default PreviewTable;

