+  // Malformed or cyclic metadata must not recurse forever. Treat any
+  // unreachable branch as a separate root and keep its local showLevel.
+  index.nodes.forEach((node) => {
+    if (visited.has(node.key)) return;
+    const showLevel = normalizeShowLevel(node.showLevel);
+    visitBranchChildren(
+      index,
+      node,
+      (childNode, depth) => {
+        visited.add(childNode.key);
+        if (depth >= showLevel) collapsedNodeKeys.add(childNode.key);
+      },
+      1,
+      new Set()
+    );
+  });
+
+  return collapsedNodeKeys;
+}
+
+export function getHiddenRowsForCollapsedNodes(index: TreeIndex, collapsedNodeKeys: Set<string>) {
+  const hiddenRows = new Set<number>();
+  const visited = new Set<string>();
+
+  function visit(node: TreeNode, hasCollapsedAncestor: boolean, path: Set<string>) {
+    if (path.has(node.key)) return;
+
+    visited.add(node.key);
+    const nextPath = new Set(path);
+    nextPath.add(node.key);
+    const hideChildren = hasCollapsedAncestor || collapsedNodeKeys.has(node.key);
+
+    node.children.forEach((childRow) => {
+      if (hideChildren) hiddenRows.add(childRow);
+
+      const childNode = index.nodes.get(getTreeNodeKey(childRow, node.col));
+      if (childNode) visit(childNode, hideChildren, nextPath);
+    });
   }

-  dfs(current, trees);
+  index.roots.forEach((rootKey) => {
+    const root = index.nodes.get(rootKey);
+    if (root) visit(root, false, new Set());
+  });
+
+  index.nodes.forEach((node) => {
+    if (!visited.has(node.key)) visit(node, false, new Set());
+  });
+
+  return hiddenRows;
+}

-  return [...new Set(childrenRows.flat())];
+function getValidRows(hot: Core, rows: Iterable<number>) {
+  const rowCount = hot.countRows();
+  return Array.from(rows).filter((row) => Number.isInteger(row) && row >= 0 && row < rowCount);
 }

-export { findChildrenRows };
+function applyTreeHiddenRows(hot: Core, previousRows: Set<number>, targetRows: Set<number>, force = false) {
+  const hiddenRowsPlugin = hot.getPlugin('hiddenRows');
+  const rowsToShow = getValidRows(
+    hot,
+    force ? previousRows : Array.from(previousRows).filter((row) => !targetRows.has(row))
+  );
+  const rowsToHide = getValidRows(
+    hot,
+    force ? targetRows : Array.from(targetRows).filter((row) => !previousRows.has(row))
+  );
+
+  if (rowsToShow.length) hiddenRowsPlugin.showRows(rowsToShow);
+  if (rowsToHide.length) hiddenRowsPlugin.hideRows(rowsToHide);
+}
+
+function syncTreeCellMeta(hot: Core, index: TreeIndex, collapsedNodeKeys: Set<string>) {
+  index.nodes.forEach((node) => {
+    hot.setCellMeta(node.row, node.col, 'children', node.children);
+    hot.setCellMeta(node.row, node.col, 'expanded', !collapsedNodeKeys.has(node.key));
+  });
+}
+
+export function initializeTreeRows(hot: Core, treeRows: TreeRowMeta[] = [], cells: TreeRowMeta[] = []) {
+  const previousState = treeStateByHot.get(hot);
+  const index = buildTreeIndex(mergeTreeRows(treeRows, cells));
+  const collapsedNodeKeys = createInitialCollapsedNodeKeys(index);
+  const hiddenRows = getHiddenRowsForCollapsedNodes(index, collapsedNodeKeys);
+
+  // loadData() can reset Handsontable's index maps. Reapply the complete target
+  // state instead of relying only on the difference from the previous sheet.
+  applyTreeHiddenRows(hot, previousState?.hiddenRows ?? new Set(), hiddenRows, true);
+  syncTreeCellMeta(hot, index, collapsedNodeKeys);
+  treeStateByHot.set(hot, { index, collapsedNodeKeys, hiddenRows });
+}
+
+export function toggleTreeNode(hot: Core, row: number, col: number) {
+  const state = treeStateByHot.get(hot);
+  const key = getTreeNodeKey(row, col);
+  const node = state?.index.nodes.get(key);
+  if (!state || !node?.children.length) return false;
+
+  if (state.collapsedNodeKeys.has(key)) {
+    state.collapsedNodeKeys.delete(key);
+  } else {
+    state.collapsedNodeKeys.add(key);
+  }
+
+  const hiddenRows = getHiddenRowsForCollapsedNodes(state.index, state.collapsedNodeKeys);
+  applyTreeHiddenRows(hot, state.hiddenRows, hiddenRows);
+  syncTreeCellMeta(hot, state.index, state.collapsedNodeKeys);
+  state.hiddenRows = hiddenRows;
+  hot.render();
+  return true;
+}
