130	export function handleLoadGlobalSettings(hot: HotTableClass, cells, globalSettings) {
131	  const mergeCells = filterCoveredMergeCells(getMergeCells(cells, globalSettings));
132	  const normalizedCells =
133	    cells
134	      ?.filter((c) => {
135	        const row = Number(c?.row);
136	        const col = Number(c?.col);
137	        if (!Number.isFinite(row) || !Number.isFinite(col)) return true;
138	        return !isCoveredCell(row, col, mergeCells);
139	      })
140	      .map((c) => {
141	        if (!c) return c;
142	        const { rowspan, colspan, hidden, mergeParent, ...cell } = c;
143	        if (!cell?.className) return cell;
144	        const next = stripNoOpBgFillFromClassName(cell.className);
145	        const className = next.trim() ? next : defaultClassName;
146	        return { ...cell, className };
147	      }) ?? cells;
148	
149	  const aggregateClass = stripNoOpBgFillFromClassName(globalSettings?.className ?? '');
150	  const usedClassName: Set<string> = new Set(aggregateClass.split(' ').filter(Boolean));
151	
152	  const { hotInstance } = hot;
153	  if (hotInstance) {
154	    registerTableCellRootCleanup(hotInstance);
155	    syncPreviewStyleRules(hotInstance, buildPreviewStyleRules(usedClassName));
156	  }
157	
158	  const cellsBounds = getCellsBounds(cells);
159	  let rowCount = normalizeCount(globalSettings?.rowCount ?? globalSettings?.rows, defaultRowCount);
160	  let colCount = normalizeCount(globalSettings?.colCount ?? globalSettings?.cols, defaultColCount);
161	  rowCount = Math.max(rowCount, cellsBounds.rowCount || defaultRowCount);
162	  colCount = Math.max(colCount, cellsBounds.colCount || defaultColCount);
163	
164	  mergeCells.forEach((item) => {
165	    colCount = Math.max(colCount, item.col + item.colspan);
166	    rowCount = Math.max(rowCount, item.row + item.rowspan);
167	  });
168	
169	  const manualColumnWidths: any[] = [];
170	  const manualRowHeights: any[] = [];
171	
172	  if (globalSettings?.widths && globalSettings?.widths.length > 0) {
173	    globalSettings?.widths.forEach(({ width, col }) => {
174	      manualColumnWidths[col] = width;
175	    });
176	  }
177	
178	  if (globalSettings?.heights && globalSettings?.heights.length > 0) {
179	    globalSettings?.heights.forEach(({ height, row }) => {
180	      manualRowHeights[row] = height;
181	    });
182	  }
183	
184	  hotInstance?.suspendRender();
185	
186	  // 先设置列宽和行高
187	  const colWidthsArr = Array.from({ length: colCount }, (_, i) => manualColumnWidths[i] || defaultColWidths);
188	  const rowHeightsArr = Array.from({ length: rowCount }, (_, i) => manualRowHeights[i] || defaultRowHeights);
189	
190	  hotInstance?.updateSettings({
191	    colWidths: colWidthsArr,
192	    rowHeights: rowHeightsArr,
193	
194	    minRows: rowCount,
195	    minCols: colCount,
196	    mergeCells: createVirtualizedMergeCellsSettings()
197	  });
198	
199	  // 更新sheet数据：loadData + updateSettings
200	  hotInstance?.loadData([[]]);
201	
202	  // 更新单元格
203	  hotInstance?.updateSettings({
204	    cell: normalizedCells
205	  });
206	
207	  // Keep logical merges intact while preventing them from expanding the rendered viewport.
208	  hotInstance?.updateSettings({
209	    mergeCells: createVirtualizedMergeCellsSettings(mergeCells)
210	  });
211	
212	  // Initialize tree visibility from the configured default display level.
213	  if (hotInstance) {
214	    initializeTreeRows(hotInstance, globalSettings?.treeRows ?? [], normalizedCells ?? []);
215	  }
216	
217	  hotInstance?.resumeRender();
218	
219	  // 再更新冻结
220	  const frozen = globalSettings?.frozen || {
221	    rowStart: 0,
222	    colStart: 0
223	  };
224	
225	  // 报表模式下才需要设置冻结
226	  !getIsMobile() &&
227	    isReport() &&
228	    hotInstance?.updateSettings({
229	      fixedRowsTop: frozen.rowStart,
230	      fixedColumnsStart: frozen.colStart
280	    hot,
281	    force ? targetRows : Array.from(targetRows).filter((row) => !previousRows.has(row))
282	  );
283	
284	  if (rowsToShow.length) hiddenRowsPlugin.showRows(rowsToShow);
285	  if (rowsToHide.length) hiddenRowsPlugin.hideRows(rowsToHide);
286	}
