288	function syncTreeCellMeta(hot: Core, index: TreeIndex, collapsedNodeKeys: Set<string>) {
289	  index.nodes.forEach((node) => {
290	    hot.setCellMeta(node.row, node.col, 'children', node.children);
291	    hot.setCellMeta(node.row, node.col, 'expanded', !collapsedNodeKeys.has(node.key));
292	  });
293	}
