295	export function initializeTreeRows(hot: Core, treeRows: TreeRowMeta[] = [], cells: TreeRowMeta[] = []) {
296	  const previousState = treeStateByHot.get(hot);
297	  const index = buildTreeIndex(mergeTreeRows(treeRows, cells));
298	  const collapsedNodeKeys = createInitialCollapsedNodeKeys(index);
299	  const hiddenRows = getHiddenRowsForCollapsedNodes(index, collapsedNodeKeys);
300	
301	  // loadData() can reset Handsontable's index maps. Reapply the complete target
302	  // state instead of relying only on the difference from the previous sheet.
303	  applyTreeHiddenRows(hot, previousState?.hiddenRows ?? new Set(), hiddenRows, true);
304	  syncTreeCellMeta(hot, index, collapsedNodeKeys);
305	  treeStateByHot.set(hot, { index, collapsedNodeKeys, hiddenRows });
306	}
