308	export function toggleTreeNode(hot: Core, row: number, col: number) {
309	  const state = treeStateByHot.get(hot);
310	  const key = getTreeNodeKey(row, col);
311	  const node = state?.index.nodes.get(key);
312	  if (!state || !node?.children.length) return false;
313	
314	  if (state.collapsedNodeKeys.has(key)) {
315	    state.collapsedNodeKeys.delete(key);
316	  } else {
317	    state.collapsedNodeKeys.add(key);
318	  }
319	
320	  const hiddenRows = getHiddenRowsForCollapsedNodes(state.index, state.collapsedNodeKeys);
321	  applyTreeHiddenRows(hot, state.hiddenRows, hiddenRows);
322	  syncTreeCellMeta(hot, state.index, state.collapsedNodeKeys);
323	  state.hiddenRows = hiddenRows;
324	  hot.render();
325	  return true;
326	}

