  1	import { stopPropagation } from '@newgrand/udp-ui/es/functionalComponent/table/util';
  2	import Handsontable from 'handsontable';
  3	import {
  4	  getBorderByDirection,
  5	  getRenderCellProperties,
  6	  isInFrozen,
  7	  optimizeRender,
  8	  resetCellRenderStyle,
  9	  resetSkippedCellRender,
 10	  setIsLastTreeChildren
 11	} from '../utils';
 12	import './style.less';
 13	import { TreeLine } from './treeExpandLine';
 14	import { toggleTreeNode } from './utils';
 15	
 16	export default function treeRender(
 17	  this: Handsontable.Core,
 18	  instance: Handsontable.Core,
 19	  TD: any,
 20	  row: number,
 21	  col: number,
 22	  prop: string | number,
 23	  value: any,
 24	  cellProperties: Handsontable.CellProperties
 25	) {
 26	  const renderCellProperties = getRenderCellProperties(instance, row, col, cellProperties);
 27	  if (!renderCellProperties) {
 28	    resetSkippedCellRender(TD, row, col);
 29	    return;
 30	  }
 31	  cellProperties = renderCellProperties;
 32	  row = cellProperties.row;
 33	  col = cellProperties.col;
 34	  resetCellRenderStyle(TD, row, col);
 35	  optimizeRender(TD, row, col, isInFrozen(row, col, cellProperties, instance));
 36	
 37	  setIsLastTreeChildren(cellProperties, instance);
 38	
 39	  TD.className = cellProperties.className;
 40	  TD.classList.remove('htMiddle');
 41	  TD.classList.remove('htBottom');
 42	
 43	  let totalHeight = 0;
 44	  for (let i = 0; i < (cellProperties.rowspan || 1); i++) {
 45	    const rowHeight = instance.getRowHeight(row + i);
 46	    totalHeight += rowHeight;
 47	  }
 48	  let totalWidth = 0;
 49	  for (let i = 0; i < (cellProperties.colspan || 1); i++) {
 50	    const colWidth = instance.getColWidth(col + i);
 51	    totalWidth += colWidth;
 52	  }
 53	
 54	  if (cellProperties?.cellBorders) {
 55	    for (const direction in cellProperties?.cellBorders) {
 56	      if (Object.prototype.hasOwnProperty.call(cellProperties?.cellBorders, direction)) {
 57	        const border = cellProperties?.cellBorders[direction];
 58	        if (!border.hide) {
 59	          getBorderByDirection(direction, border, TD);
 60	        }
 61	      }
 62	    }
 63	  }
 64	
 65	  TD.style.padding = 0;
 66	
 67	  TD[`root-${row}_${col}`].render(
 68	    <TreeComponent hot={instance} cellProperties={cellProperties} width={totalWidth - 2} height={totalHeight - 2} />
 69	  );
 70	}
 71	
 72	const TreeComponent = ({
 73	  hot,
 74	  width,
 75	  height,
 76	  cellProperties
 77	}: {
 78	  width: number;
 79	  height: number;
 80	  cellProperties: Handsontable.CellProperties;
 81	  hot: Handsontable.Core;
 82	}) => {
 83	  const { row, col, children, treeLevel = 1, formatData, expanded = false, isLast } = cellProperties;
 84	
 85	  const switchExpand = (e) => {
 86	    stopPropagation(e);
 87	    toggleTreeNode(hot, row, col);
 88	  };
 89	
 90	  return (
 91	    <div className="treeHeader" style={{ width, height }}>
 92	      <TreeLine treeLevel={treeLevel} isLast={isLast} />
 93	      <span
 94	        className={`row-expand-icon ${isLast && children?.length === 0 ? 'row-expand-icon-last' : ''}`}
 95	        onClick={children?.length > 0 ? switchExpand : undefined}
 96	      >
 97	        {children?.length > 0 ? <span className={`icon ${expanded ? ' icon-expanded' : 'icon-collapsed'}`} /> : null}
 98	      </span>
 99	      <span style={{ marginLeft: '4px' }}>{formatData}</span>
100	    </div>
101	  );
102	};
 15	
 16	/**
 17	 * 判断当前单元格是否在冻结区域
 18	 * 是的话，缓存react组件，防止重复渲染
 19	 */
 20	export function isInFrozen(
 21	  row: number,
 22	  col: number,
 23	  cellProperties: Handsontable.CellProperties,
 24	  hot: Handsontable.Core
 25	) {
 26	  // 如果fixedColumnsStart有值，代表有冻结
 27	  if (cellProperties.fixedColumnsStart) {
 28	    const fixedRowsStart = hot.getSettings().fixedRowsTop;
 29	    if (row <= (fixedRowsStart ?? 0) && col <= (cellProperties.fixedColumnsStart ?? 0)) {
 30	      return true;
 31	    }
 32	  }
 33	  return false;
 34	}
 35	
 36	export function optimizeRender(TD, row, col, _lazyRender?: boolean) {
 37	  const rootKey = getCellRootKey(row, col);
 38	  releaseCellReactRoots(TD, rootKey);
 39	  if (TD[rootKey]) return;
 40	
 41	  empty(TD);
 42	  TD[rootKey] = createRoot(TD);
 43	}
 44	
 45	export function getRenderCellProperties(
 46	  instance: Handsontable.Core,
 47	  row: number,
 48	  col: number,
 49	  cellProperties: Handsontable.CellProperties
 50	): (Handsontable.CellProperties & { row: number; col: number }) | null {
 51	  if (row === cellProperties.row && col === cellProperties.col) {
 52	    return cellProperties as Handsontable.CellProperties & { row: number; col: number };
 53	  }
 54	
 55	  const mergePlugin = instance.getPlugin('mergeCells') as any;
 56	  const mergeParent = mergePlugin?.mergedCellsCollection?.get(row, col);
 57	  if (!mergeParent) return null;
 58	
 59	  return {
 60	    ...instance.getCellMeta(mergeParent.row, mergeParent.col),
 61	    row: mergeParent.row,
 62	    col: mergeParent.col,
 63	    rowspan: mergeParent.rowspan,
 64	    colspan: mergeParent.colspan
 65	  };
 66	}
 67	
 68	export function resetCellRenderStyle(TD: HTMLTableCellElement, row: number, col: number) {
 69	  TD.setAttribute('htCoord', `${row}-${col}`);
 70	  TD.removeAttribute('size');
 71	  TD.style.padding = '';
 72	  TD.style.borderTop = '';
 73	  TD.style.borderRight = '';
 74	  TD.style.borderBottom = '';
 75	  TD.style.borderLeft = '';

