interface ReportSchemaInfo {
  schema?: string;
}

function parseSchema(schema?: string) {
  try {
    const value = JSON.parse(schema || '[]');
    return Array.isArray(value) ? value : [];
  } catch {
    return [];
  }
}

function clone<T>(value: T): T {
  if (value === undefined || value === null) return value;
  return JSON.parse(JSON.stringify(value));
}

function getConfiguredShowLevelsByColumn(schemaSheet: any) {
  const levelsByColumn = new Map<number, number>();
  const ambiguousColumns = new Set<number>();

  (schemaSheet?.cells ?? []).forEach((cell: any) => {
    if (cell?.cellType !== 'tree') return;

    const col = Number(cell?.col);
    const rawShowLevel = cell?.showLevel ?? cell?.treeConfig?.showLevel ?? cell?.cellData?.treeConfig?.showLevel;
    if (rawShowLevel === null || rawShowLevel === undefined || rawShowLevel === '') return;

    const showLevel = Number(rawShowLevel);
    if (!Number.isInteger(col) || col < 0 || !Number.isFinite(showLevel)) return;

    if (levelsByColumn.has(col) && levelsByColumn.get(col) !== showLevel) {
      ambiguousColumns.add(col);
      return;
    }
    levelsByColumn.set(col, Math.max(1, Math.floor(showLevel)));
  });

  ambiguousColumns.forEach((col) => levelsByColumn.delete(col));
  return levelsByColumn;
}

/**
 * The design-preview API expands a configured tree cell into many runtime
 * cells, but older services omit treeRows and treeConfig from the response.
 * Restore the configured level by column from the submitted design schema.
 */
export function applySchemaTreeShowLevels<T>(data: T, reportInfo?: ReportSchemaInfo): T {
  if (!Array.isArray(data)) return data;

  const schema = parseSchema(reportInfo?.schema);
  if (!schema.length) return data;

  const nextData = clone(data);
  nextData.forEach((sheet, index) => {
    const sheetKey = String(sheet?.sheetKey ?? index);
    const schemaSheet = schema.find((item, schemaIndex) => String(item?.sheetKey ?? schemaIndex) === sheetKey);
    const levelsByColumn = getConfiguredShowLevelsByColumn(schemaSheet);
    if (!levelsByColumn.size) return;

    (sheet?.cells ?? []).forEach((cell: any) => {
      if (cell?.cellType !== 'tree') return;
      if (cell?.showLevel != null || cell?.treeConfig?.showLevel != null) return;

      const showLevel = levelsByColumn.get(Number(cell?.col));
      if (showLevel != null) cell.showLevel = showLevel;
    });
  });

  return nextData;
}

content.text:
interface ReportSchemaInfo {
  schema?: string;
}

function parseSchema(schema?: string) {
  try {
    const value = JSON.parse(schema || '[]');
    return Array.isArray(value) ? value : [];
  } catch {
    return [];
  }
}

function clone<T>(value: T): T {
  if (value === undefined || value === null) return value;
  return JSON.parse(JSON.stringify(value));
}

function getConfiguredShowLevelsByColumn(schemaSheet: any) {
  const levelsByColumn = new Map<number, number>();
  const ambiguousColumns = new Set<number>();

  (schemaSheet?.cells ?? []).forEach((cell: any) => {
    if (cell?.cellType !== 'tree') return;

    const col = Number(cell?.col);
    const rawShowLevel = cell?.showLevel ?? cell?.treeConfig?.showLevel ?? cell?.cellData?.treeConfig?.showLevel;
    if (rawShowLevel === null || rawShowLevel === undefined || rawShowLevel === '') return;

    const showLevel = Number(rawShowLevel);
    if (!Number.isInteger(col) || col < 0 || !Number.isFinite(showLevel)) return;

    if (levelsByColumn.has(col) && levelsByColumn.get(col) !== showLevel) {
      ambiguousColumns.add(col);
      return;
    }
    levelsByColumn.set(col, Math.max(1, Math.floor(showLevel)));
  });

  ambiguousColumns.forEach((col) => levelsByColumn.delete(col));
  return levelsByColumn;
}

/**
 * The design-preview API expands a configured tree cell into many runtime
 * cells, but older services omit treeRows and treeConfig from the response.
 * Restore the configured level by column from the submitted design schema.
 */
export function applySchemaTreeShowLevels<T>(data: T, reportInfo?: ReportSchemaInfo): T {
  if (!Array.isArray(data)) return data;

  const schema = parseSchema(reportInfo?.schema);
  if (!schema.length) return data;

  const nextData = clone(data);
  nextData.forEach((sheet, index) => {
    const sheetKey = String(sheet?.sheetKey ?? index);
    const schemaSheet = schema.find((item, schemaIndex) => String(item?.sheetKey ?? schemaIndex) === sheetKey);
    const levelsByColumn = getConfiguredShowLevelsByColumn(schemaSheet);
    if (!levelsByColumn.size) return;

    (sheet?.cells ?? []).forEach((cell: any) => {
      if (cell?.cellType !== 'tree') return;
      if (cell?.showLevel != null || cell?.treeConfig?.showLevel != null) return;

      const showLevel = levelsByColumn.get(Number(cell?.col));
      if (showLevel != null) cell.showLevel = showLevel;
    });
  });

  return nextData;
}

