import { getCellRootKey, releaseCellReactRoots } from '@/components/report/preview/plugins/cellRootLifecycle';
import { createRoot } from 'react-dom/client';
import { empty } from './hot-utils';

export function optimizeRender(TD, row, col) {
  const rootKey = getCellRootKey(row, col);
  releaseCellReactRoots(TD, rootKey);
  if (TD[rootKey]) return;

  empty(TD);
  TD[rootKey] = createRoot(TD);
}

