 61	    return tableRef.current ?? undefined;
 62	  }
 63	
 64	  const onChange = async (key: string) => {
 65	    window.dispatchEvent(new CustomEvent('reportPreviewBeforeSheetChange', { detail: { sheetKey: defaultSheet } }));
 66	
 67	    NG.getPageInstance().umiDispatch({
 68	      type: 'updateHotLoading',
 69	      payload: true
 70	    });
 71	
 72	    await NG.delay(300);
 73	
 74	    NG.getPageInstance().umiDispatch({
 75	      type: 'updateDefaultSheet',
 76	      payload: key
 77	    });
 78	
 79	    // 工作流页面的切换逻辑
 80	    if (pathname.includes('reportWorkFlow')) {
 81	      NG.getPageInstance().umiDispatch({
 82	        type: 'changeReportSheet',
 83	        payload: sheets[key]
 84	      });
 85	      NG.getPageInstance().umiDispatch({
 86	        type: 'updateHotLoading',
 87	        payload: false
 88	      });
 89	    }
 90	  };
 91	
 92	  // sheets 或 userLayouts（行列布局调整）变化时重新渲染
 93	  // 使用 useMemo 稳定化 dep，避免 useSelector 整体 state 刷新导致的假触发
 94	  const sheetsKey = useMemo(() => sheets, [sheets]);
 95	  const userLayoutsKey = useMemo(() => userLayouts, [userLayouts]);
 96	
 97	  useEffect(() => {
 98	    if (!tableRef.current) return;
 99	    if (!sheets || (sheets && sheets.length <= 0)) return;
100	    handleLoadFetchedData(sheets);
101	  }, [sheetsKey, tableRef.current, userLayoutsKey]);
102	
103	  /**
104	   * 处理获取到的数据
105	   *  */
106	  const handleLoadFetchedData = useRefCallback((data) => {
107	    // tab标签页
108	    const sheetTabs: any[] = [];
109	    // 1、处理sheet列表 显示成tab
110	    data?.forEach((sheet, index) => {
111	      sheetTabs.push({
112	        label: sheet.sheetName,
113	        key: sheet.sheetKey || index.toString()
114	      });
115	    });
116	
117	    // 2、设置当前点击、活跃的sheet标签
118	    setTabItems(sheetTabs);
119	
120	    const legalKey = defaultSheet ?? '0';
121	
122	    // 将useLayout配置合并到globalSettings
123	    const newGlobalSettings = NG.deepCopy(data[legalKey]?.globalSettings ?? {});
124	    const useLayout = userLayouts?.find((item) => item.sheetKey === legalKey);
125	    if (useLayout) {
126	      Object.assign(newGlobalSettings, useLayout.layoutConfig);
127	    }
128	    // 3、加载当前sheet数据
129	    // 4、加载设置
130	    const hot = getHotInstance();
131	    if (!hot) return;
132	    handleLoadGlobalSettings(hot, data[legalKey]?.cells, newGlobalSettings);
133	  });
134	
135	  return (
136	    <Tabs
137	      // 只是隐藏
138	      hidden={noSheets}
139	      className={className}
140	      onChange={onChange}
141	      activeKey={defaultSheet ?? '0'}
142	      type="card"
143	      items={tabItems}
144	    />
145	  );
146	};
