  1	interface ReportSchemaInfo {
  2	  schema?: string;
  3	}
  4	
  5	function parseSchema(schema?: string) {
  6	  try {
  7	    const value = JSON.parse(schema || '[]');
  8	    return Array.isArray(value) ? value : [];
  9	  } catch {
 10	    return [];
 11	  }
 12	}
 13	
 14	function clone<T>(value: T): T {
 15	  if (value === undefined || value === null) return value;
 16	  return JSON.parse(JSON.stringify(value));
 17	}
 18	
 19	function getConfiguredShowLevelsByColumn(schemaSheet: any) {
 20	  const levelsByColumn = new Map<number, number>();
 21	  const ambiguousColumns = new Set<number>();
 22	
 23	  (schemaSheet?.cells ?? []).forEach((cell: any) => {
 24	    if (cell?.cellType !== 'tree') return;
 25	
 26	    const col = Number(cell?.col);
 27	    const rawShowLevel = cell?.showLevel ?? cell?.treeConfig?.showLevel ?? cell?.cellData?.treeConfig?.showLevel;
 28	    if (rawShowLevel === null || rawShowLevel === undefined || rawShowLevel === '') return;
 29	
 30	    const showLevel = Number(rawShowLevel);
 31	    if (!Number.isInteger(col) || col < 0 || !Number.isFinite(showLevel)) return;
 32	
 33	    if (levelsByColumn.has(col) && levelsByColumn.get(col) !== showLevel) {
 34	      ambiguousColumns.add(col);
 35	      return;
 36	    }
 37	    levelsByColumn.set(col, Math.max(1, Math.floor(showLevel)));
 38	  });
 39	
 40	  ambiguousColumns.forEach((col) => levelsByColumn.delete(col));
 41	  return levelsByColumn;
 42	}
 43	
 44	/**
 45	 * The design-preview API expands a configured tree cell into many runtime
 46	 * cells, but older services omit treeRows and treeConfig from the response.
 47	 * Restore the configured level by column from the submitted design schema.
 48	 */
 49	export function applySchemaTreeShowLevels<T>(data: T, reportInfo?: ReportSchemaInfo): T {
 50	  if (!Array.isArray(data)) return data;
 51	
 52	  const schema = parseSchema(reportInfo?.schema);
 53	  if (!schema.length) return data;
 54	
 55	  const nextData = clone(data);
 56	  nextData.forEach((sheet, index) => {
 57	    const sheetKey = String(sheet?.sheetKey ?? index);
 58	    const schemaSheet = schema.find((item, schemaIndex) => String(item?.sheetKey ?? schemaIndex) === sheetKey);
 59	    const levelsByColumn = getConfiguredShowLevelsByColumn(schemaSheet);
 60	    if (!levelsByColumn.size) return;
 61	
 62	    (sheet?.cells ?? []).forEach((cell: any) => {
 63	      if (cell?.cellType !== 'tree') return;
 64	      if (cell?.showLevel != null || cell?.treeConfig?.showLevel != null) return;
 65	
 66	      const showLevel = levelsByColumn.get(Number(cell?.col));
 67	      if (showLevel != null) cell.showLevel = showLevel;
 68	    });
 69	  });
 70	
 71	  return nextData;
 72	}

