 83	export function resetSkippedCellRender(TD: HTMLTableCellElement, row: number, col: number) {
 84	  const td = TD as any;
 85	  releaseCellReactRoots(td);
 86	
 87	  empty(TD);
 88	  TD.className = '';
 89	  TD.removeAttribute('rowspan');
 90	  TD.removeAttribute('colspan');
 91	  TD.removeAttribute('size');
 92	  TD.setAttribute('htCoord', `${row}-${col}`);
 93	  TD.style.padding = '';
 94	  TD.style.borderTop = '';
 95	  TD.style.borderRight = '';
 96	  TD.style.borderBottom = '';
 97	  TD.style.borderLeft = '';
 98	  TD.style.height = '';
 99	  TD.style.display = '';
100	}
