102	/**
103	 * 1、判断当前单元格是否是最后一行
104	 * 2、返回父节点坐标
105	 * @param cellProperties
106	 * @param instance
107	 * @returns
108	 */
109	export function setIsLastTreeChildren(cellProperties: Handsontable.CellProperties, instance: Handsontable.Core) {
110	  let parentCoord: number[] | null = null;
111	
112	  if (cellProperties.treeParent !== null && cellProperties.treeParent >= 0) {
113	    // 得到父节点坐标
114	    parentCoord = [cellProperties.treeParent, cellProperties.col];
115	    const parentCellMeta = instance.getCellMeta(parentCoord[0], parentCoord[1]);
116	
117	    if (Math.max(...(parentCellMeta?.children ?? [])) === Number(cellProperties.row)) {
118	      cellProperties.isLast = true;
119	    }
120	  }
121	
122	  return { parentCoord };
123	}
  1	const cellRootPrefix = 'root-';
  2	
  3	interface CellReactRoot {
  4	  unmount?: () => void;
  5	}
  6	
  7	export function getCellRootKey(row: number, col: number) {
  8	  return `${cellRootPrefix}${row}_${col}`;
  9	}
 10	
 11	export function releaseCellReactRoots(target: Record<string, any>, keepKey?: string) {
 12	  Object.keys(target).forEach((key) => {
 13	    if (!key.startsWith(cellRootPrefix) || key === keepKey) return;
 14	    const root = target[key] as CellReactRoot | undefined;
 15	    root?.unmount?.();
 16	    delete target[key];
 17	  });
 18	}
 19	
 20	export function releaseTableCellReactRoots(rootElement?: HTMLElement | null) {
 21	  rootElement?.querySelectorAll('td').forEach((cell) => releaseCellReactRoots(cell as any));
 22	}
 23	
 24	interface TableWithDestroyHook {
 25	  rootElement?: HTMLElement | null;
 26	  addHookOnce: (...args: any[]) => void;
 27	}
 28	
 29	const registeredTables = new WeakSet<object>();
 30	
 31	export function registerTableCellRootCleanup(table: TableWithDestroyHook) {
 32	  if (registeredTables.has(table)) return;
 33	  registeredTables.add(table);
 34	  table.addHookOnce('beforeDestroy', () => {
 35	    releaseTableCellReactRoots(table.rootElement);
 36	    registeredTables.delete(table);
 37	  });
 38	}

